entries[293661] = { ["name"] = "Instabile Resonanz: Sturm", ["text"] = "150 Meter Reichweite\nSofort\nMarkiert Spielercharaktere 15 Sek. lang mit dem Sturm. Berührung mit dem Orkanrufer leitet die Macht gefahrlos in das Relikt ab.\n\nNach 15 Sek. explodiert die ' Instabile Resonanz ' und fügt allen Spielercharakteren innerhalb von 10 Metern 65425 Schattenschaden zu. Die Explosion wird ebenfalls ausgelöst, wenn zwei Spielercharaktere mit verschiedenen Resonanzen miteinander in Kontakt kommen." }
entries[293662] = { ["name"] = "Instabile Resonanz: Ozean", ["text"] = "150 Meter Reichweite\nSofort\nMarkiert Spielercharaktere 15 Sek. lang mit dem Ozean. Berührung mit dem Dreizack der Tiefsee leitet die Macht gefahrlos in das Relikt ab.\n\nNach 15 Sek. explodiert die ' Instabile Resonanz ' und fügt allen Spielercharakteren innerhalb von 10 Metern 65425 Schattenschaden zu. Die Explosion wird ebenfalls ausgelöst, wenn zwei Spielercharaktere mit verschiedenen Resonanzen miteinander in Kontakt kommen." }
entries[293663] = { ["name"] = "Instabile Resonanz: Leere", ["text"] = "150 Meter Reichweite\nSofort\nMarkiert Spielercharaktere 15 Sek. lang mit der Leere. Berührung mit dem Leerenstein leitet die Macht gefahrlos in das Relikt ab.\n\nNach 15 Sek. explodiert die ' Instabile Resonanz ' und fügt allen Spielercharakteren innerhalb von 10 Metern 65425 Schattenschaden zu. Die Explosion wird ebenfalls ausgelöst, wenn zwei Spielercharaktere mit verschiedenen Resonanzen miteinander in Kontakt kommen." }
entries[293664] = { ["name"] = "Neurale Autonomie", ["text"] = "Sofort\nMacht Euch immun gegen manche Ärgernisse durch andere Spieler." }
entries[293665] = { ["name"] = "Instabile Resonanz", ["text"] = "Sofort\nMarkiert Spielercharaktere 15 Sek. lang mit Sturm, Ozean und Leere. Wenn sie die entsprechenden Relikte berühren, wird die Macht sicher in das jeweilige Relikt geleitet.\n\nNach 15 Sek. explodiert die ' Instabile Resonanz ' und fügt allen Spielercharakteren innerhalb von 10 Metern 65425 Schattenschaden zu. Die Explosion wird ebenfalls ausgelöst, wenn zwei Spielercharaktere mit verschiedenen Resonanzen miteinander in Kontakt kommen." }
